 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v not in (0, 1, 2, 5, 9)}
    # Stamp is the rare color, distinct from the noisy background palette.
    if len(colors) != 1:
        colors = {v for row in grid for v in row if v not in (0, 1, 2, 5, 9)}
    color = next(iter(colors))
    pts = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == color]
    r0, r1 = min(r for r,c in pts), max(r for r,c in pts)
    c0, c1 = min(c for r,c in pts), max(c for r,c in pts)
    shape = [(r-r0,c-c0) for r,c in pts]
    sh, sw = r1-r0+1, c1-c0+1
    # Background color is the unique value absent from the noisy field? Target marks are zero.
    bg = 0
    out = [row[:] for row in grid]
    for r in range(h-sh+1):
        for c in range(w-sw+1):
            if (r,c) == (r0,c0):
                continue
            if all(grid[r+dr][c+dc] == bg for dr,dc in shape):
                for dr,dc in shape:
                    out[r+dr][c+dc] = color
    return out
